/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];

// 矩阵行数，矩阵列数，区域敌军数量上限
let n, m, k;
// 地图矩阵
let matrix;
// 访问矩阵
let visited;

rl.on("line", (line) => {
  lines.push(line);

  if (lines.length == 1) {
    [n, m, k] = lines[0].split(" ").map(Number);
  }

  if (n != undefined && lines.length == n + 1) {
    lines.shift();
    matrix = lines;
    visited = new Array(n).fill(0).map(() => new Array(m).fill(false));

    console.log(getResult());

    lines.length = 0;
  }
});

function getResult() {
  let ans = 0;

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      if (visited[i][j] || matrix[i][j] == "#") continue;
      // 如果(i,j)位置未访问过，且不是墙，则进入广搜，广搜结果是广搜区域内的敌军数量，如果数量小于k，则该区域符合要求
      ans += bfs(i, j) < k ? 1 : 0;
    }
  }

  return ans;
}

// 上、下、左、右偏移量
const offsets = [
  [-1, 0],
  [1, 0],
  [0, -1],
  [0, 1],
];

function bfs(i, j) {
  // 该区域敌军数量
  let count = 0;

  // 如果源位置是E，则敌军数量+1
  if (matrix[i][j] == "E") count += 1;

  // 标记源位置访问过
  visited[i][j] = true;

  // 广搜依赖于队列结构，先进先出
  const queue = [[i, j]];

  while (queue.length > 0) {
    const [x, y] = queue.shift();

    // 遍历该位置的上下左右
    for (let offset of offsets) {
      const newX = x + offset[0];
      const newY = y + offset[1];

      // 如果新位置不越界，且未访问过，且不是墙，则继续广搜
      if (
        newX >= 0 &&
        newX < n &&
        newY >= 0 &&
        newY < m &&
        !visited[newX][newY] &&
        matrix[newX][newY] != "#"
      ) {
        // 如果对应位置是E，则敌军数量+1
        if (matrix[newX][newY] == "E") count += 1;

        // 标记该位置访问过
        visited[newX][newY] = true;

        queue.push([newX, newY]);
      }
    }
  }

  return count;
}

