import java.util.Arrays;
import java.util.LinkedList;
import java.util.Scanner;

public class Main {
  static int n; // 地图行数
  static int m; // 地图列数
  static int k; // 区域敌军人数上限值
  static char[][] matrix; // 地图矩阵
  static boolean[][] visited; // 访问矩阵

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int[] tmp = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    n = tmp[0];
    m = tmp[1];
    k = tmp[2];

    visited = new boolean[n][m];

    matrix = new char[n][];
    for (int i = 0; i < n; i++) {
      matrix[i] = sc.nextLine().toCharArray();
    }

    System.out.println(getResult());
  }

  public static int getResult() {
    int ans = 0;

    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (visited[i][j] || matrix[i][j] == '#') continue;
        // 如果(i,j)位置未访问过，且不是墙，则进入广搜，广搜结果是广搜区域内的敌军数量，如果数量小于k，则该区域符合要求
        ans += bfs(i, j) < k ? 1 : 0;
      }
    }

    return ans;
  }

  // 上、下、左、右偏移量
  static int[][] offsets = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

  public static int bfs(int i, int j) {
    // 该区域敌军数量
    int count = 0;

    // 标记该位置访问过
    visited[i][j] = true;

    // 如果对应位置是E，则敌军数量+1
    if (matrix[i][j] == 'E') count += 1;

    // 广搜依赖于队列结构，先进先出
    LinkedList<int[]> queue = new LinkedList<>();
    queue.add(new int[] {i, j});

    while (queue.size() > 0) {
      int[] pos = queue.removeFirst();
      int x = pos[0], y = pos[1];

      // 遍历该位置的上下左右
      for (int[] offset : offsets) {
        int newX = x + offset[0];
        int newY = y + offset[1];

        // 如果新位置不越界，且未访问过，且不是墙，则继续广搜
        if (newX >= 0
            && newX < n
            && newY >= 0
            && newY < m
            && !visited[newX][newY]
            && matrix[newX][newY] != '#') {
          // 标记该位置访问过
          visited[newX][newY] = true;

          // 如果对应位置是E，则敌军数量+1
          if (matrix[newX][newY] == 'E') count += 1;

          queue.add(new int[] {newX, newY});
        }
      }
    }

    return count;
  }
}

