#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 101

typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();
void addLast_LinkedList(LinkedList *link, int ele);
int removeFirst_LinkedList(LinkedList* link);

// 地图行数,地图列数,区域敌军人数上限值
int n, m, k;
// 地图矩阵
char matrix[MAX_SIZE][MAX_SIZE] = {'\0'};
// 访问矩阵
int visited[MAX_SIZE][MAX_SIZE] = {0};
// 上下左右的方位偏移量
int offsets[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

int getResult();
int bfs(int i, int j);

int main() {
    scanf("%d %d %d", &n, &m, &k);

    for(int i = 0; i < n; i++) {
        scanf("%s", matrix[i]);
    }

    printf("%d\n", getResult());

    return 0;
}

int getResult() {
    int ans = 0;

    for(int i=0; i<n; i++) {
        for(int j=0; j<m; j++) {
            if(visited[i][j] || matrix[i][j] == '#') continue;
            ans += bfs(i, j) < k ? 1 : 0;
        }
    }

    return ans;
}

int bfs(int i, int j) {
    // 该区域敌军数量
    int count = 0;

    // 标记该位置访问过
    visited[i][j] = 1;

    // 如果对应位置是E，则敌军数量+1
    if(matrix[i][j] == 'E') count++;

    // 广搜依赖于队列结构，先进先出
    LinkedList* queue = new_LinkedList();
    addLast_LinkedList(queue, i * m + j);

    // 遍历该位置的上下左右
    while(queue->size > 0) {
        int pos = removeFirst_LinkedList(queue);

        int x = pos / m;
        int y = pos % m;

        for(int a = 0; a < 4; a++) {
            int newX = x + offsets[a][0];
            int newY = y + offsets[a][1];

            // 如果新位置不越界，且未访问过，且不是墙，则继续广搜
            if(newX >= 0 && newX < n && newY >= 0 && newY < m && !visited[newX][newY] && matrix[newX][newY] != '#') {
                // 标记该位置访问过
                visited[newX][newY] = 1;

                // 如果对应位置是E，则敌军数量+1
                if(matrix[newX][newY] == 'E') count++;

                addLast_LinkedList(queue, newX * m + newY);
            }
        }
    }

    return count;
}


LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

int removeFirst_LinkedList(LinkedList* link) {
    if(link->size == 0) exit(-1);

    ListNode* removed = link->head;

    if(link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    int res = removed->ele;

    free(removed);

    return res;
}
